Preparing the data
We begin by loading our dataset.

data &lt;- tar_read(fw_with_env) |&gt;
  filter(dist_to_env &lt; 5) |&gt;
  mutate(
    salinity = sali_mean |&gt; as.numeric()
  ) |&gt;
  select(
    year,
    survey,
    log_species_richness,
    log_trophic_richness,
    longitude,
    latitude,
    salinity
  ) |&gt;
  mutate(is_nurse = if_else(survey == "nurse", 1, 0))

plot_data_on_map(data)








Here is the map of our sampling points.

Salinity niches
Here we are interested in caracterising species salinity niches, that is, the salinity range where they can live. To avoid having to many species, we filter the more rare species.

n_op &lt;- data |&gt;
  pull(trait) |&gt;
  unique() |&gt;
  length()

threshold &lt;- 0.01

occurence &lt;- data |&gt;
  tidyr::unnest(species) |&gt;
  group_by(species) |&gt;
  summarise(n = n(), .groups = "drop")

rare_species &lt;- occurence |&gt;
  filter(n &lt; threshold * n_op) |&gt;
  pull(species)

niche &lt;- data |&gt;
  select(species, salinity) |&gt;
  tidyr::unnest(species) |&gt;
  filter_out(species %in% rare_species) |&gt;
  group_by(species) |&gt;
  summarise(
    salinity_med = median(salinity),
    salinity_q10 = quantile(salinity, 0.1),
    salinity_q90 = quantile(salinity, 0.9),
    salinity_min = min(salinity),
    salinity_max = max(salinity),
    .groups = "drop"
  )


niche &lt;- niche |&gt;
  arrange(salinity_med) |&gt;
  mutate(
    species = factor(species, levels = species)
  )

ggplot(niche, aes(y = species)) +
  geom_segment(
    aes(x = salinity_q10, xend = salinity_q90, yend = species),
    linewidth = 1.5,
  ) +
  geom_segment(
    aes(x = salinity_min, xend = salinity_max, yend = species),
    linewidth = 0.5,
  ) +
  geom_point(aes(x = salinity_med), size = 2) +
  labs(x = "Salinity [PSU]", y = NULL)








We see that most species have wide salinity niche, meaning that they can endure high variability in salinity, these species notably comprise migratory species such as the Anguilla or the Alosa.
We find that most species have a wide salinity niche, which is not surprising for species found in estuaries. That said, a few species seem to be marine such as

Arnoglossus laterna
Buglossidium luteum

which are both marine and dermersal species that live on sandy bottoms.
This analysis invites to couple our food web analysis with species traits to better understand what drives food web structure changes. In this regard, information about species migratory behaviour and whether they are benthic or pelagic. For example, change in food web structure could signal the apparition of a bentho-pelagic coupling.

Collinearity between environmental variables
Before fitting statistical models, we check whether environmental variables are correlated with each other, which would make it hard to separate their individual effects. We subsample points to keep the pair plot readable and fast to render.


Code
env_vars &lt;- setdiff(names(riversea::rename_amobio()), c("date", "sandre_code"))

data |&gt;
  st_drop_geometry() |&gt;
  select(all_of(env_vars)) |&gt;
  slice_sample(n = 5000) |&gt;
  GGally::ggpairs(columns = env_vars)

Temporal coverage


Code
yearly_counts &lt;- dplyr::bind_rows(
  rephy_data |&gt;
    dplyr::mutate(year = lubridate::year(date)) |&gt;
    dplyr::count(year, name = "n") |&gt;
    dplyr::mutate(source = "REPHY station"),
  foodwebs |&gt;
    dplyr::count(year, name = "n") |&gt;
    dplyr::mutate(source = "Fishing operation")
)

ggplot(yearly_counts, aes(x = year, y = n, fill = source)) +
  geom_col(position = "identity", alpha = 0.6) +
  scale_fill_manual(
    values = c(
      "REPHY station" = "#1b9e77",
      "Fishing operation" = "#d95f02"
    )
  ) +
  scale_x_continuous(breaks = scales::breaks_pretty()) +
  labs(x = NULL, y = "Number of observations", fill = NULL)









Both datasets have decent overlap from the late 1990s/2000s onwards, which is where we should expect the interpolation to be best supported.

Size coverage per species
For each species, the diet table should define a diet over contiguous stages covering the whole size range, from 0 to unbounded. We look for three failure modes: gaps between consecutive stages, a first stage that does not start at 0, and a species missing altogether from the larvae stage.

size_gaps &lt;- diet |&gt;
  arrange(species, length_min) |&gt;
  group_by(species) |&gt;
  mutate(
    previous_length_max = lag(length_max),
    gap = length_min - previous_length_max
  ) |&gt;
  ungroup() |&gt;
  # A small gap is left on purpose between stages to avoid assigning a
  # boundary size to both the stage below and above.
  filter(!is.na(gap) & gap &gt; 1e-3) |&gt;
  select(species, stage, length_min, previous_length_max, gap)
size_gaps

# A tibble: 0 × 5
# ℹ 5 variables: species &lt;chr&gt;, stage &lt;chr&gt;, length_min &lt;dbl&gt;,
#   previous_length_max &lt;dbl&gt;, gap &lt;dbl&gt;



species_no_larvae &lt;- diet |&gt;
  group_by(species) |&gt;
  summarise(has_larvae = "larvae" %in% stage, .groups = "drop") |&gt;
  filter(!has_larvae)
species_no_larvae

# A tibble: 0 × 2
# ℹ 2 variables: species &lt;chr&gt;, has_larvae &lt;lgl&gt;



species_not_starting_at_zero &lt;- diet |&gt;
  group_by(species) |&gt;
  summarise(min_length = min(length_min), .groups = "drop") |&gt;
  filter(min_length &gt; 1e-3)
species_not_starting_at_zero

# A tibble: 0 × 2
# ℹ 2 variables: species &lt;chr&gt;, min_length &lt;dbl&gt;


If the three tables above are empty, every species’ diet is defined over its full size range and foodwebbuilder::build_metaweb() should not error out on a missing diet interval.

Diet composition by fish origin
We split species into three groups, reusing the same survey-membership logic as the venn diagram above: freshwater (found only in river), marine (found only in nurse/pomet), and migratory (found in both). For each group, we look at the average diet composition across resource categories (from the literature-curated diet table, not the constructed food webs), normalised so each group’s bars sum to 1.


Code
species_origin &lt;- size |&gt;
  distinct(species_valid, survey) |&gt;
  group_by(species_valid) |&gt;
  summarise(
    surveys = paste(sort(unique(survey)), collapse = ","), .groups = "drop"
  ) |&gt;
  mutate(
    has_river = grepl("river", surveys),
    has_marine = grepl("nurse|pomet", surveys),
    origin = case_when(
      has_river & !has_marine ~ "freshwater",
      !has_river & has_marine ~ "marine",
      has_river & has_marine ~ "migratory"
    )
  )

species_diet &lt;- diet |&gt;
  select(species, all_of(resource_list)) |&gt;
  group_by(species) |&gt;
  summarise(across(everything(), mean), .groups = "drop") |&gt;
  inner_join(
    species_origin |&gt; select(species_valid, origin),
    by = c("species" = "species_valid")
  )

origin_diet &lt;- species_diet |&gt;
  group_by(origin) |&gt;
  summarise(across(all_of(resource_list), mean), .groups = "drop") |&gt;
  tidyr::pivot_longer(
    -origin, names_to = "resource_cat", values_to = "value"
  ) |&gt;
  group_by(origin) |&gt;
  mutate(share = value / sum(value)) |&gt;
  ungroup()

ggplot(
  origin_diet,
  aes(x = factor(origin, levels = c("freshwater", "migratory", "marine")),
      y = share, fill = resource_cat)
) +
  geom_col(width = 0.6) +
  scale_fill_brewer(palette = "Set3") +
  labs(x = NULL, y = "Share of diet (resource categories)", fill = "Resource")









Freshwater and migratory species share a similar diet profile, both with a substantial insect component; marine species show almost no insect consumption (aquatic insects being a specifically freshwater resource) and rely more on zooplankton and phytoplankton instead.
